INSERT INTO blog_edicao_posts (id, titulo, categoria, resumo, autor, tempo_leitura_min, data_publicacao, imagem_url, conteudo_md) VALUES
('art-filo-01', 'Aristóteles e a Justiça: A Diferença entre Justiça Comutativa e Distributiva', 'Filosofia', 'Mergulhe no Livro V de Ética a Nicômaco de Aristóteles e compreenda a equidade e a aplicação da justiça no ordenamento contemporâneo.', 'Redação Estudos Jurídicos', 10, '2026-08-05', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/aristoteles.png', $md$Na obra **Ética a Nicômaco (Livro V)**, Aristóteles desenvolveu uma das classificações mais duradouras da Filosofia do Direito, definindo a justiça como a virtude perfeita de dar a cada um o que lhe é devido.

---

### ⚖️ As Duas Formas da Justiça Particular

- **Justiça Distributiva**: Trata da partilha de bens, honras e obrigações pela comunidade aos seus membros. Baseia-se na **proporção geométrica** (*tratar os iguais igualmente e os desiguais na medida de suas desigualdades*).
- **Justiça Comutativa (Corretiva)**: Trata de transações entre indivíduos (contratos ou delitos). Baseia-se na **proporção aritmética** (restauração do equilíbrio alterado).$md$),
('art-filo-02', 'Hart x Dworkin: O Duelo Filosófico entre o Positivismo e a Moral no Direito', 'Filosofia', 'Descubra a histórica controvérsia sobre a Separação entre Direito e Moral segundo H.L.A. Hart e a Crítica dos Princípios de Ronald Dworkin.', 'Redação Estudos Jurídicos', 11, '2026-08-04', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/hart-dworkin.png', $md$O debate entre **H.L.A. Hart (O Conceito de Direito)** e **Ronald Dworkin (Levando os Direitos a Sério)** moldou o pensamento jurídico moderno sobre a relação entre regras escritas, moralidade e interpretação dos juízes nos casos difíceis (*hard cases*).

---

### ⚔️ O Confronto de Ideias

| Conceito | H.L.A. Hart (Positivismo Jurídico) | Ronald Dworkin (Pós-Positivismo) |
| :--- | :--- | :--- |
| **Definição de Direito** | Sistema composto por regras primárias e secundárias (Regra de Reconhecimento). | O Direito inclui regras e **princípios morais** implícitos na integridade da comunidade. |
| **Casos Difíceis** | Na lacuna da lei, o juiz possui **discricionariedade** para criar a norma. | O juiz **não** tem discricionariedade livre; deve buscar a resposta correta à luz da integridade. |$md$),
('art-filo-03', 'Justiça como Equidade de John Rawls: O Véu da Ignorância e a Sociedade Justa', 'Filosofia', 'Como criar regras sociais imparciais? Conheça a Posição Originária e o Princípio da Diferença formulados por John Rawls em Uma Teoria da Justiça.', 'Redação Estudos Jurídicos', 10, '2026-08-03', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/filosofia.png', $md$Em **Uma Teoria da Justiça (1971)**, o filósofo político norte-americano **John Rawls** propôs um experimento de pensamento revolucionário para determinar os princípios fundamentais de uma sociedade justa: a **Posição Originária sob o Véu da Ignorância**.

---

### 💡 Os Dois Princípios Fundamentais da Justiça

1. **Princípio da Liberdade Igual**: Cada pessoa tem o mesmo direito irrevogável a um esquema plenamente adequado de liberdades básicas iguais.
2. **Princípio da Diferença**: As desigualdades sociais e econômicas só são justificáveis se trouxerem o maior benefício possível aos membros menos favorecidos da sociedade.$md$),
('art-filo-04', 'O Leviatã de Thomas Hobbes: Por Que Abrimos Mão da Liberdade pelo Estado?', 'Filosofia', 'Entenda o Estado de Natureza ("a guerra de todos contra todos") e o pacto social Hobbesiano que fundamentou a soberania estatal absoluta.', 'Redação Estudos Jurídicos', 9, '2026-08-02', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/filosofia.png', $md$Na sua célebre obra **Leviatã (1651)**, Thomas Hobbes argumentou que, no **Estado de Natureza** (sem leis ou governo), a vida humana seria *"solitária, pobre, sórdida, embrutecida e curta"*, gerando a guerra de todos contra todos (*homo homini lupus*).

---

> 📜 **O Pacto de Submissão**:
> Para escapar da insegurança da morte violenta, os indivíduos celebram um contrato social onde transferem todo o seu poder de força ao Estado soberano (o **Leviatã**), que garante a paz social em troca de obediência.$md$),
('art-filo-05', 'O Imperativo Categórico de Kant: A Ética do Dever Aplicada à Justiça', 'Filosofia', 'A filosofia moral de Immanuel Kant: a diferença entre imperativos hipotéticos e categóricos e a dignidade humana como valor supremo inestimável.', 'Redação Estudos Jurídicos', 9, '2026-08-01', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/filosofia.png', $md$Na **Fundamentação da Metafísica dos Costumes (1785)**, Immanuel Kant estabeleceu que uma ação só possui valor moral autêntico quando realizada por **dever**, e não por interesse particular ou conveniência.

---

> 📜 **A Segunda Formulação do Imperativo Categórico**:
> *"Age de tal maneira que uses a humanidade, tanto na tua pessoa como na pessoa de qualquer outro, sempre e simultaneamente como fim, e nunca simplesmente como meio."*$md$);